void ls2k300_hardware_init()
{
  /* GPIO50/51 配置为 I2C1 功能 (MAIN_FUNC = 0x3) */
  ls_pinmux_pin_setup(50, LS_PINMUX_MODE_AS_MAIN_FUNC);
  ls_pinmux_pin_setup(51, LS_PINMUX_MODE_AS_MAIN_FUNC);

  /* SPI0 引脚复用配置
   * GPIO64 (SPI0_CLK)  -> MAIN_FUNC (0x3)
   * GPIO65 (SPI0_MISO) -> MAIN_FUNC (0x3)
   * GPIO66 (SPI0_MOSI) -> MAIN_FUNC (0x3)
   * GPIO67 (SPI0_CSN1) -> GPIO (0x0), 用于 MCP3204 软件片选
   */
  ls_pinmux_pin_setup(64, LS_PINMUX_MODE_AS_MAIN_FUNC);
  ls_pinmux_pin_setup(65, LS_PINMUX_MODE_AS_MAIN_FUNC);
  ls_pinmux_pin_setup(66, LS_PINMUX_MODE_AS_MAIN_FUNC);
  ls_pinmux_pin_setup(67, LS_PINMUX_MODE_AS_GPIO);

  /* SPI2 (SPIIO2) 引脚复用配置
   * GPIO64 (SPI2_CLK)  -> MAIN_FUNC (0x3) — 与 SPI0 共用
   * GPIO65 (SPI2_MISO) -> MAIN_FUNC (0x3) — 与 SPI0 共用
   * GPIO66 (SPI2_MOSI) -> MAIN_FUNC (0x3) — 与 SPI0 共用
   * GPIO85 (Flash CS)  -> GPIO (0x0), 软件片选
   */
  /* PWM2 引脚复用：GPIO88 -> SECOND_FUNC (0x2)，硬件 PWM 输出 */
  ls_pinmux_pin_setup(88, LS_PINMUX_MODE_AS_SECOND_FUNC);

  /* Blind-write GPIO85 pinmux (GPIO80-95 group, register 0x160004A4).
   * Must be AFTER all RMW pinmux calls — RMW reads 0xFFFFFFFF and corrupts
   * GPIO85 bits.  Value: GPIO85=b00(GPIO), GPIO88=b10(SECOND_FUNC),
   * all others=b11(MAIN_FUNC).
   */
  *(volatile uint32_t *)PHYS_TO_UNCACHED(0x160004A4) = 0xFFFEF3FF;

  /* GPIO85 配置为输出，CS 默认高（空闲态）.
   * 注意 DIR 寄存器极性：0=输出，1=输入（见 ls2k300_gpio.c gpio_setpintype）.
   */

  writeb(0, (volatile void *)(PHYS_TO_UNCACHED(LS2K300_GPIO_BASE) + 0x800 + 85));  /* DIR=0 → OUTPUT */
  writeb(1, (volatile void *)(PHYS_TO_UNCACHED(LS2K300_GPIO_BASE) + 0x900 + 85));  /* OUT=high (CS idle) */

  /* Enable SPIIO2/SPIIO3 clock gate (GENERAL_CFG5 bits 17-18) */

  {
    volatile uint32_t *cfg5 =
        (volatile uint32_t *)PHYS_TO_UNCACHED(LS2K300_GENERAL_CFG5);
    *cfg5 |= (3U << 17);
  }
}


/****************************************************************************
 * Public Functions
 ****************************************************************************/

int ls2k300_bringup(void)
{
  int ret = OK;

  _info("bringup: start\n");

  ls2k300_hardware_init();

#ifdef CONFIG_FS_PROCFS
  _info("bringup: mounting procfs\n");
  ret = mount(NULL, "/proc", "procfs", 0, NULL);
  if (ret < 0)
    {
      serr("ERROR: Failed to mount procfs at %s: %d\n", "/proc", ret);
    }
#endif

#ifdef CONFIG_LS2K300_ADC
  _info("bringup: ADC\n");
  {
    FAR struct adc_dev_s *adc = ls2k300_adc_initialize();
    if (adc != NULL)
      {
        ret = adc_register("/dev/adc0", adc);
        if (ret < 0)
          {
            serr("ERROR: adc_register failed: %d\n", ret);
          }
      }
  }
#endif

#ifdef CONFIG_LS2K300_I2C0
  _info("bringup: I2C0\n");
  {
    FAR struct i2c_master_s *i2c = ls2k300_i2c_initialize(0);
    if (i2c != NULL)
      {
        ret = i2c_register(i2c, 0);
        if (ret < 0)
          {
            serr("ERROR: i2c_register failed for I2C0: %d\n", ret);
          }
      }
  }
#endif

#ifdef CONFIG_LS2K300_I2C1
  _info("bringup: I2C1\n");
  {
    FAR struct i2c_master_s *i2c = ls2k300_i2c_initialize(1);
    if (i2c != NULL)
      {
        ret = i2c_register(i2c, 1);
        if (ret < 0)
          {
            serr("ERROR: i2c_register failed for I2C1: %d\n", ret);
          }
      }
  }
#endif

#ifdef CONFIG_LS2K300_I2C2
  _info("bringup: I2C2\n");
  {
    FAR struct i2c_master_s *i2c = ls2k300_i2c_initialize(2);
    if (i2c != NULL)
      {
        ret = i2c_register(i2c, 2);
        if (ret < 0)
          {
            serr("ERROR: i2c_register failed for I2C2: %d\n", ret);
          }
      }
  }
#endif

#ifdef CONFIG_LS2K300_I2C3
  _info("bringup: I2C3\n");
  {
    FAR struct i2c_master_s *i2c = ls2k300_i2c_initialize(3);
    if (i2c != NULL)
      {
        ret = i2c_register(i2c, 3);
        if (ret < 0)
          {
            serr("ERROR: i2c_register failed for I2C3: %d\n", ret);
          }
      }
  }
#endif

#ifdef CONFIG_LS2K300_THERMAL
  _info("bringup: THERMAL\n");
  ret = ls2k300_thermal_initialize();
  if (ret < 0)
    {
      serr("ERROR: ls2k300_thermal_initialize failed: %d\n", ret);
    }
#endif

#ifdef CONFIG_LS2K300_PWM0
  _info("bringup: PWM0\n");
  ret = ls2k300_pwm_initialize(0);
  if (ret < 0)
    {
      serr("ERROR: ls2k300_pwm_initialize failed for PWM0: %d\n", ret);
    }
#endif

#ifdef CONFIG_LS2K300_PWM1
  _info("bringup: PWM1\n");
  ret = ls2k300_pwm_initialize(1);
  if (ret < 0)
    {
      serr("ERROR: ls2k300_pwm_initialize failed for PWM1: %d\n", ret);
    }
#endif

#ifdef CONFIG_LS2K300_PWM2
  _info("bringup: PWM2\n");
  ret = ls2k300_pwm_initialize(2);
  if (ret < 0)
    {
      serr("ERROR: ls2k300_pwm_initialize failed for PWM2: %d\n", ret);
    }
#endif

#ifdef CONFIG_LS2K300_PWM3
  _info("bringup: PWM3\n");
  ret = ls2k300_pwm_initialize(3);
  if (ret < 0)
    {
      serr("ERROR: ls2k300_pwm_initialize failed for PWM3: %d\n", ret);
    }
#endif

#ifdef CONFIG_LS2K300_SPI0
  _info("bringup: SPI0\n");
  {
    FAR struct spi_dev_s *spi = ls2k300_spiflash_initialize(0);
    if (spi == NULL)
      {
        serr("ERROR: ls2k300_spiflash_initialize failed for SPI0\n");
      }
  }
#endif

#ifdef CONFIG_LS2K300_SPI1
  _info("bringup: SPI1\n");
  {
    FAR struct spi_dev_s *spi = ls2k300_spiflash_initialize(1);
    if (spi == NULL)
      {
        serr("ERROR: ls2k300_spiflash_initialize failed for SPI1\n");
      }
  }
#endif

#ifdef CONFIG_LS2K300_SPIIO3
  _info("bringup: SPIIO3\n");
  {
    FAR struct spi_dev_s *spi = ls2k300_spiio_initialize(1);
    if (spi == NULL)
      {
        serr("ERROR: ls2k300_spiio_initialize failed for SPIIO3\n");
      }
  }
#endif

#ifdef CONFIG_LS2K300_WDT
  _info("bringup: WDT\n");
  ret = ls2k300_wdt_initialize();
  if (ret < 0)
    {
      serr("ERROR: ls2k300_wdt_initialize failed: %d\n", ret);
    }
#endif

#ifdef CONFIG_LS2K300_PINCTRL
  _info("bringup: PINCTRL\n");
  ret = ls2k300_pinctrl_initialize();
  if (ret < 0)
    {
      serr("ERROR: ls2k300_pinctrl_initialize failed: %d\n", ret);
    }
#endif

#ifdef CONFIG_LS2K300_GPIO
  _info("bringup: GPIO\n");
  ret = ls2k300_gpio_initialize();
  if (ret < 0)
    {
      serr("ERROR: ls2k300_gpio_initialize failed: %d\n", ret);
    }
#endif

#ifdef CONFIG_LS2K300_SPIIO2
  /* SPIIO2 SPI Flash init: after pinctrl and GPIO are ready.
   * GPIO85 pinmux was blind-written in hardware_init(); re-assert here
   * because ls2k300_gpio_initialize() resets all pins to GPIO_INPUT_PIN.
   */

  {
    uintptr_t gpio_base = PHYS_TO_UNCACHED(LS2K300_GPIO_BASE);

    /* Blind-write pinmux again (GPIO init may have RMW'd it) */

    *(volatile uint32_t *)PHYS_TO_UNCACHED(0x160004A4) = 0xFFFEF3FF;

    /* DIR=0 (output), OUT=1 (CS idle high) */

    writeb(0, (volatile void *)(gpio_base + 0x800 + 85));
    writeb(1, (volatile void *)(gpio_base + 0x900 + 85));
  }

  _info("bringup: SPIIO2 SPI Flash\n");
  {
    FAR struct spi_dev_s *spi = ls2k300_spiio_initialize(0);
    if (spi == NULL)
      {
        serr("ERROR: ls2k300_spiio_initialize failed for SPIIO2\n");
      }
    else
      {
        /* Software reset flash chip (recover from stale state) */

        SPI_SELECT(spi, SPIDEV_FLASH(0), true);
        SPI_SEND(spi, 0x66);  /* Enable Reset */
        SPI_SELECT(spi, SPIDEV_FLASH(0), false);
        up_udelay(1);

        SPI_SELECT(spi, SPIDEV_FLASH(0), true);
        SPI_SEND(spi, 0x99);  /* Reset */
        SPI_SELECT(spi, SPIDEV_FLASH(0), false);
        up_mdelay(30);

        /* Probe GD25 flash */

        FAR struct mtd_dev_s *mtd = gd25_initialize(spi, 0);
        if (mtd == NULL)
          {
            serr("ERROR: gd25_initialize failed on SPIIO2\n");
          }
        else
          {
            ret = register_mtddriver("/dev/spiflash", mtd, 0755, NULL);
            if (ret < 0)
              {
                serr("ERROR: register_mtddriver failed: %d\n", ret);
              }
            else
              {
                mkdir("/spiflash", 0777);
                ret = nx_mount("/dev/spiflash", "/spiflash",
                               "littlefs", 0, "autoformat");
                if (ret < 0)
                  {
                    serr("ERROR: Failed to mount LittleFS: %d\n", ret);
                  }
                else
                  {
                    _info("bringup: LittleFS mounted at /spiflash\n");
                  }
              }
          }
      }
  }
#endif

#ifdef CONFIG_LS2K300_ETHERNET
  _info("bringup: ETHERNET\n");
  ret = ls2k300_ethernet_initialize();
  if (ret < 0)
    {
      serr("ERROR: ls2k300_ethernet_initialize failed: %d\n", ret);
    }
#endif

  _info("bringup: done\n");

  return ret;
}
