# filtering the backup (final) defconfig. Preserves the backup's exact line
# order, so the final commit (all groups active) is byte-identical to the
# backup.
#
# Usage: gen_defconfig.sh <active-groups...>
#   groups: adc rtc i2c thermal pwm spi spiio wdt gpio ethernet
set -e
BACKUP=test-backup-pre-rebase
FILE=boards/loongarch/ls2k300/hummingbird-ls2k300/configs/nsh/defconfig
active=" $* "
all=(adc rtc i2c thermal pwm spi spiio wdt gpio ethernet)
rem=()
for g in "${all[@]}"; do
  case "$g" in
    adc)      p='^CONFIG_ADC_FIFOSIZE=|^CONFIG_DEBUG_ANALOG=|^CONFIG_DEBUG_ANALOG_ERROR=|^CONFIG_LS2K300_ADC=';;
    rtc)      p='^CONFIG_LS2K300_RTC=';;
    i2c)      p='^CONFIG_LS2K300_I2C=|^CONFIG_LS2K300_I2C[0-3]=|^CONFIG_I2C_DRIVER=';;
    thermal)  p='^CONFIG_LS2K300_THERMAL=';;
    pwm)      p='^CONFIG_LS2K300_PWM[0-3]?=';;
    spi)      p='^CONFIG_LS2K300_SPI[01]?=';;
    spiio)    p='^CONFIG_LS2K300_SPIIO[23]?=';;
    wdt)      p='^CONFIG_LS2K300_WDT=';;
    gpio)     p='^CONFIG_LS2K300_GPIO=|^CONFIG_LS2K300_PINCTRL=';;
    ethernet) p='^CONFIG_LS2K300_ETHERNET=|^CONFIG_NETDEV_LATEINIT=|^CONFIG_NETINIT_NETLOCAL=|^CONFIG_NET_ICMP_SOCKET=|^CONFIG_NET_SOCKOPTS=|^CONFIG_SYSTEM_PING=|^CONFIG_SYSTEM_PING_STACKSIZE=';;
  esac
  if [[ "$active" != *"$g"* ]]; then
    rem+=("$p")
  fi
done
IFS='|'; remre="${rem[*]}"; unset IFS
git show "$BACKUP:$FILE" | grep -vE "$remre"

