#!/usr/bin/env bash
# Generate ls2k300_bringup.c for a given set of active driver groups by
# filtering the backup (final) file: remove top-level #ifdef CONFIG_<guard>
# ... #endif blocks belonging to inactive groups. Preserves final block order,
# so the final commit (all groups active) is byte-identical to the backup.
#
# Usage: gen_bringup.sh <active-groups...>
#   groups: adc rtc i2c thermal pwm spi spiio wdt gpio ethernet
set -e
BACKUP=test-backup-pre-rebase
FILE=boards/loongarch/ls2k300/hummingbird-ls2k300/src/ls2k300_bringup.c
active=" $* "

# Map each group to the space-separated CONFIG guards of its bringup blocks.
guards_for() {
  case "$1" in
    adc)      echo "LS2K300_ADC";;
    rtc)      echo "";;                       # RTC has no bringup block
    i2c)      echo "LS2K300_I2C LS2K300_I2C0 LS2K300_I2C1 LS2K300_I2C2 LS2K300_I2C3";;
    thermal)  echo "LS2K300_THERMAL";;
    pwm)      echo "LS2K300_PWM LS2K300_PWM0 LS2K300_PWM1 LS2K300_PWM2 LS2K300_PWM3";;
    spi)      echo "LS2K300_SPI LS2K300_SPI0 LS2K300_SPI1";;
    spiio)    echo "LS2K300_SPIIO LS2K300_SPIIO2 LS2K300_SPIIO3";;
    wdt)      echo "LS2K300_WDT";;
    gpio)     echo "LS2K300_GPIO LS2K300_PINCTRL";;   # GPIO + pinctrl are one commit
    ethernet) echo "LS2K300_ETHERNET";;
  esac
}

# Build the removal guard set (guards of INACTIVE groups).
rem=""
for g in adc rtc i2c thermal pwm spi spiio wdt gpio ethernet; do
  if [[ "$active" != *"$g"* ]]; then
    rem="$rem $(guards_for "$g")"
  fi
done
rem=$(echo "$rem" | tr ' ' '\n' | grep -v '^$' | sort -u | tr '\n' ' ')

export rem
awk '
BEGIN {
  n = split(ENVIRON["rem"], a, " ")
  for (i = 1; i <= n; i++) if (a[i] != "") rem[a[i]] = 1
  depth = 0          # current #if nesting depth
  skipdepth = -1     # depth at which we started skipping (-1 = not skipping)
}
{
  # Detect preprocessor conditionals
  if ($0 ~ /^[[:space:]]*#[[:space:]]*(ifdef|ifndef|if)/) {
    if (depth == 0 && $0 ~ /^[[:space:]]*#[[:space:]]*ifdef[[:space:]]+CONFIG_/) {
      g = $0
      sub(/^[[:space:]]*#[[:space:]]*ifdef[[:space:]]+CONFIG_/, "", g)
      g = gensub(/[^A-Z0-9_].*$/, "", "g", g)
      if (g in rem) {
        skipdepth = depth   # 0
      }
    }
    depth++
    if (skipdepth >= 0) next
  } else if ($0 ~ /^[[:space:]]*#[[:space:]]*(endif|else|elif)/) {
    if (skipdepth >= 0) {
      if ($0 ~ /^[[:space:]]*#[[:space:]]*endif/) {
        depth--
        if (depth == skipdepth) {
          skipdepth = -1
          # also swallow one following blank line
          getline nextline
          if (nextline !~ /^[[:space:]]*$/) print nextline
          next
        }
      } else {
        # #else/#elif inside skipped block
        if ($0 ~ /^[[:space:]]*#[[:space:]]*(else|elif)/) {
          # do nothing, keep skipping
        }
      }
      next
    } else {
      if ($0 ~ /^[[:space:]]*#[[:space:]]*endif/) depth--
    }
  } else {
    if (skipdepth >= 0) next
  }
  print
}
' <(git show "$BACKUP:$FILE")
